""" Converts a bcd value to a decimal value
    :param value: The value to unpack from bcd
    :returns: The number in decimal form
    """
def _convert_from_bcd(bcd: Any) -> object {
    (place, decimal) = (1, 0);
    while (bcd > 0) {
        nibble = bcd & 15;
        decimal += nibble * place;
        bcd >>= 4;
        place *= 10;
    }
    return decimal;
}

"""
    Move a path from one directory to another. Given the directory the path is
    currently in, moves it to be in the second. The path below the given
    directory level remains the same.
    """
def move_path(current_dir: Any, new_dir: Any, path: Any) -> object {
    if (current_dir[-1] != '/') {
        current_dir += '/';
    }
    if (new_dir[-1] != '/') {
        new_dir += '/';
    }
    return path.replace(current_dir, new_dir, 1);
}

