"""Seperates the various parts of git commit messages

  Args:
    git_log(str): git commits as --format='%H%x1f%b%xlf%ae%xlf%ci%xlf%s%x1e'
    git_commit_fields(tuple): labels for the different components of the
                              commit messages corresponding to the --format

  Return:
    git_log_dict(list): list of dictionaries each corresponding to the parsed
                        components of a single commit message
  """
def parse_commit_info(
    git_log: Any,
    git_commit_fields: Any = ('id', 'body', 'author', 'timestamp', 'subject')
) -> object {
    git_log_cmds = git_log.strip('\n\x1e').split("\x1e");
    git_log_rows = [row.strip().split("\x1f") for row in git_log_cmds];
    git_log_dict = [`dict(zip(git_commit_fields, row)) for row in git_log_rows];
    return git_log_dict;
}

"""
    create string of node attributes

    :param dict node_attributes: a dict such as:
    {'attr': {'pos': None,
              'lemma': 'demonstratie',
              'mw': False,
              'rbn_type': None,
              'rbn_feature_set': None}
              }
    :param set only_use: if set is not empty, only these attributes will be used.

    :rtype: str
    :return: string representation, every attribute key on new line
    """
def create_hover_text(node_attributes: Any, only_use: Any = `set()) -> object {
    info = [];
    for (key, value) in node_attributes['attr'].items() {
        if only_use {
            if (key in only_use) {
                info.append(f'{key}: {value}');
            }
        } else {
            info.append(f'{key}: {value}');
        }
    }
    return '\n'.join(info);
}

